import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { X } from 'lucide-react';
import { clientService } from '../../services/clientService';
import { projectService } from '../../services/projectService';
import { clientTeamService } from '../../services/clientTeamService';
import Swal from 'sweetalert2';

export const CreateProjectModal = ({ isOpen, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    project_name: '',
    description: '',
    client_id: '',
    project_type: 'audit',
    start_date: '',
    estimated_end_date: '',
    budget: '',
    assigned_to: [],
  });
  const [loading, setLoading] = useState(false);
  const [clients, setClients] = useState([]);
  const [availableUsers, setAvailableUsers] = useState([]);

  useEffect(() => {
    if (isOpen) {
      loadClients();
      loadUsers();
    }
  }, [isOpen]);

  const loadClients = async () => {
    try {
      const data = await clientService.getAll();
      setClients(data);
    } catch (error) {
      console.error('Error loading clients:', error);
    }
  };

  const loadUsers = async () => {
    try {
      const data = await clientTeamService.getAvailableConsultants();
      console.log('📊 Usuarios cargados:', data);
      setAvailableUsers(data);
    } catch (error) {
      console.error('❌ Error loading users:', error);
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const toggleUser = (userId) => {
    setFormData(prev => ({
      ...prev,
      assigned_to: prev.assigned_to.includes(userId)
        ? prev.assigned_to.filter(id => id !== userId)
        : [...prev.assigned_to, userId]
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      await projectService.create({
        ...formData,
        budget: parseFloat(formData.budget),
      });
      
      Swal.fire({
        icon: 'success',
        title: '✅ Proyecto Creado',
        text: `${formData.project_name} ha sido creado exitosamente`,
        confirmButtonColor: '#16a34a',
      });

      onSuccess();
      onClose();
      setFormData({
        project_name: '',
        description: '',
        client_id: '',
        project_type: 'audit',
        start_date: '',
        estimated_end_date: '',
        budget: '',
        assigned_to: [],
      });
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: error.response?.data?.detail || 'Error al crear proyecto',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Crear Nuevo Proyecto</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            {/* Nombre del Proyecto */}
            <div>
              <Label htmlFor="project_name">Nombre del Proyecto *</Label>
              <Input
                id="project_name"
                name="project_name"
                value={formData.project_name}
                onChange={handleChange}
                required
                placeholder="Auditoría Ambiental 2025"
              />
            </div>

            {/* Descripción */}
            <div>
              <Label htmlFor="description">Descripción *</Label>
              <Textarea
                id="description"
                name="description"
                value={formData.description}
                onChange={handleChange}
                required
                placeholder="Descripción del proyecto..."
                rows={3}
              />
            </div>

            {/* Cliente */}
            <div>
              <Label htmlFor="client_id">Cliente *</Label>
              <Select 
                value={formData.client_id} 
                onValueChange={(value) => setFormData({ ...formData, client_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Seleccionar cliente..." />
                </SelectTrigger>
                <SelectContent>
                  {clients.map((client) => (
                    <SelectItem key={client._id} value={client._id}>
                      {client.company_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Tipo de Proyecto */}
            <div>
              <Label htmlFor="project_type">Tipo de Proyecto *</Label>
              <Select 
                value={formData.project_type} 
                onValueChange={(value) => setFormData({ ...formData, project_type: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="audit">Auditoría</SelectItem>
                  <SelectItem value="certification">Certificación</SelectItem>
                  <SelectItem value="consulting">Consultoría</SelectItem>
                  <SelectItem value="training">Capacitación</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Fechas */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="start_date">Fecha de Inicio *</Label>
                <Input
                  id="start_date"
                  name="start_date"
                  type="date"
                  value={formData.start_date}
                  onChange={handleChange}
                  required
                />
              </div>

              <div>
                <Label htmlFor="estimated_end_date">Fecha de Fin Estimada *</Label>
                <Input
                  id="estimated_end_date"
                  name="estimated_end_date"
                  type="date"
                  value={formData.estimated_end_date}
                  onChange={handleChange}
                  required
                />
              </div>
            </div>

            {/* Presupuesto */}
            <div>
              <Label htmlFor="budget">Presupuesto (USD) *</Label>
              <Input
                id="budget"
                name="budget"
                type="number"
                step="0.01"
                value={formData.budget}
                onChange={handleChange}
                required
                placeholder="5000.00"
              />
            </div>

            {/* 🔥 EQUIPO ASIGNADO - NUEVO */}
            <div>
              <Label>Equipo Asignado (Opcional)</Label>
              <p className="text-xs text-gray-500 mb-2">
                Selecciona los consultores que trabajarán en este proyecto
              </p>
              
              <div className="mt-2 space-y-2 max-h-48 overflow-y-auto border rounded-lg p-3 bg-gray-50">
                {availableUsers.length === 0 ? (
                  <div className="text-center py-4">
                    <p className="text-sm text-gray-500">Cargando usuarios...</p>
                  </div>
                ) : (
                  availableUsers.map((user) => (
                    <div
                      key={user._id}
                      className="flex items-center justify-between hover:bg-white p-2 rounded transition-colors"
                    >
                      <label className="flex items-center gap-3 flex-1 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={formData.assigned_to.includes(user._id)}
                          onChange={() => toggleUser(user._id)}
                          className="w-4 h-4 text-green-600 rounded focus:ring-green-500"
                        />
                        <div className="flex-1">
                          <p className="text-sm font-medium text-gray-900">
                            {user.full_name}
                          </p>
                          <p className="text-xs text-gray-500">{user.email}</p>
                        </div>
                      </label>
                      <Badge variant="outline" className="text-xs">
                        {user.role === 'admin' ? 'Admin' : 'Consultor'}
                      </Badge>
                    </div>
                  ))
                )}
              </div>
              
              {formData.assigned_to.length > 0 && (
                <div className="mt-2 flex items-center gap-2">
                  <Badge className="bg-green-100 text-green-700">
                    {formData.assigned_to.length} usuario(s) seleccionado(s)
                  </Badge>
                </div>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button 
              type="submit" 
              disabled={loading} 
              className="bg-green-600 hover:bg-green-700"
            >
              {loading ? 'Creando...' : 'Crear Proyecto'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};
